import TransitionSlider from '@components/transition';
import {ScrollableX} from '@components/scrollable';
import {fastRaf} from '@helpers/schedulers';
import fastSmoothScroll, {FocusDirection} from '@helpers/fastSmoothScroll';
import findUpAsChild from '@helpers/dom/findUpAsChild';
import whichChild from '@helpers/dom/whichChild';
import ListenerSetter from '@helpers/listenerSetter';
import {attachClickEvent} from '@helpers/dom/clickEvent';
import liteMode from '@helpers/liteMode';
import {ScrollableContextValue} from '@components/scrollable2';
import attachTabList from '@helpers/dom/tabList';

type OnChangeArgs = {
  element: HTMLElement;
  active: boolean;
};

type Args = {
  tabs: HTMLElement;
  content: HTMLElement,
  onClick?: (id: number, tabContent: HTMLDivElement, animate: boolean) => void | boolean | Promise<void | boolean>;
  onTransitionEnd?: () => void;
  transitionTime?: number;
  scrollableX?: ScrollableX | ScrollableContextValue;
  listenerSetter?: ListenerSetter;
  onChange?: (args: OnChangeArgs) => void;
};

export type SelectTargetArgs = {
  target: HTMLElement;
  id: number;
  animate?: boolean;
  tabs: HTMLElement;
  content?: HTMLElement;
  onClick?: Args['onClick'];
  scrollableX?: Args['scrollableX'];
  transitionTime?: number;
  prevId?: number;
  selectTab?: (id: number, animate: boolean) => void;
  onChange?: (args: OnChangeArgs) => void;
};

export async function selectTarget({
  target,
  id,
  animate = true,
  tabs,
  content,
  onClick,
  scrollableX,
  transitionTime = 200,
  prevId = -1,
  selectTab,
  onChange
}: SelectTargetArgs) {
  if(onClick) {
    const tabContent = content?.children[id] as HTMLDivElement;
    const result1 = onClick(id, tabContent, animate);
    const canChange = result1 instanceof Promise ? await result1 : result1;
    if(canChange === false) {
      return;
    }
  }

  if(!target) {
    return false;
  }

  if(scrollableX) {
    const containerEl = scrollableX.container;
    // Skip the scroll round-trip when there's no actual scrolling to do:
    //   - row has no horizontal overflow (every tab is already visible)
    //   - selecting the first tab while already at scrollLeft 0 (you can't
    //     scroll past the start to "center" it, so fastSmoothScroll
    //     clamps path to 0 and no-ops anyway)
    // Common at the moment the search panel opens — `selectTab(0)` runs
    // against a row whose scroll position is the default 0.
    const noOverflow = containerEl.scrollWidth <= containerEl.clientWidth;
    const isFirstAndAtStart = id === 0 && containerEl.scrollLeft === 0;
    if(!noOverflow && !isFirstAndAtStart) {
      fastSmoothScroll({
        container: containerEl,
        element: target.parentElement.children[id] as HTMLElement,
        position: 'center',
        forceDirection: animate ? undefined : FocusDirection.Static,
        forceDuration: transitionTime,
        axis: 'x'
      });
    }
  }

  if(!liteMode.isAvailable('animations')) {
    animate = false;
  }

  // with reduced animations the stripe steps to the tab, while the content still crossfades
  const moveStripe = animate && liteMode.isAvailable('motion');

  if(target.classList.contains('active') || id === prevId) {
    return false;
  }

  const mutateCallback = animate ? fastRaf : (cb: () => void) => cb();

  const prev = tabs.querySelector(tabs.firstElementChild.tagName.toLowerCase() + '.active') as HTMLElement;
  if(prev) {
    mutateCallback(() => {
      prev.classList.remove('active');
      onChange?.({element: prev, active: false});
    });
  }

  // a great stripe from Jolly Cobra
  if(prevId !== -1 && moveStripe) {
    const selector = '.menu-horizontal-div-item-background';
    mutateCallback(() => {
      const indicator = target.querySelector(selector) as HTMLElement;
      const previous = target.parentElement.children[prevId];
      const currentIndicator = previous?.querySelector(selector) as HTMLElement;

      // the callback runs a frame later, by which point the row may have been rebuilt or the
      // previous item removed — the stripe is decoration, so skip it rather than throw
      if(!indicator || !currentIndicator) {
        return;
      }

      currentIndicator.classList.remove('animate');
      indicator.classList.remove('animate');

      const shiftLeft = currentIndicator.parentElement.offsetLeft - indicator.parentElement.offsetLeft;
      const clientWidth = indicator.clientWidth;
      const scaleFactor = currentIndicator.clientWidth / clientWidth;
      indicator.style.transform = `translate3d(${shiftLeft}px, 0, 0)`;
      indicator.style.width = `${clientWidth * scaleFactor}px`;

      fastRaf(() => {
        indicator.classList.add('animate');
        indicator.style.transform = 'none';
        indicator.style.width = '';
      });
    });
  }

  mutateCallback(() => {
    target.classList.add('active');
    onChange?.({element: target, active: true});
  });

  selectTab?.(id, animate);
}

export function horizontalMenuObjArgs({tabs, content, onClick, onTransitionEnd, transitionTime, scrollableX, listenerSetter, onChange}: Args) {
  return horizontalMenu(tabs, content, onClick, onTransitionEnd, transitionTime, scrollableX, listenerSetter, onChange);
}

export function horizontalMenu(
  tabs: Args['tabs'],
  content: Args['content'],
  onClick?: Args['onClick'],
  onTransitionEnd?: Args['onTransitionEnd'],
  transitionTime: Args['transitionTime'] = 200,
  scrollableX?: Args['scrollableX'],
  listenerSetter?: Args['listenerSetter'],
  onChange?: Args['onChange']
) {
  const _selectTab = TransitionSlider({
    content,
    type: tabs || content.dataset.animation === 'tabs' ? 'tabs' : 'navigation',
    transitionTime,
    onTransitionEnd,
    listenerSetter
  });

  if(!tabs) {
    return _selectTab;
  }

  const detachTabList = attachTabList(tabs, content);
  listenerSetter?.addCleanup(detachTabList);

  const _selectTarget = (target: HTMLElement, id: number, animate = true) => {
    return selectTarget({
      target,
      id,
      animate,
      tabs,
      content,
      onClick,
      scrollableX,
      transitionTime,
      prevId: _selectTab.prevId(),
      selectTab: _selectTab,
      onChange
    });
  };

  const proxy = new Proxy(_selectTab, {
    apply: (target, that, args) => {
      const animate = args[1] !== undefined ? args[1] : true;

      let id: number, el: HTMLElement;
      if(args[0] instanceof HTMLElement) {
        id = whichChild(args[0]);
        el = args[0];
      } else {
        id = +args[0];
        el = (tabs.querySelector(`[data-tab="${id}"]`) || tabs.children[id]) as HTMLElement;
      }

      _selectTarget(el, id, animate);
    }
  });

  attachClickEvent(tabs, (e) => {
    let target = e.target as HTMLElement;
    target = findUpAsChild(target, tabs);
    if(!target) return false;

    let id: number;
    if(target.dataset.tab) {
      id = +target.dataset.tab;
      if(id === -1) {
        return false;
      }
    } else {
      id = whichChild(target);
    }

    _selectTarget(target, id);
  }, {listenerSetter});

  return proxy;
}
